const { Library } = require('./s1_library.js');
const { Cache } = require('./s7_cache.js');

function shelfLine(library) {
  const titles = library.titles();
  if (titles.length === 0) {
    return '(empty)';
  }
  return titles.join(', ');
}

// Export the function
module.exports = { shelfLine };

// Test asserts
const testLibrary = new Library();

// Test with empty library
console.assert(shelfLine(testLibrary) === '(empty)', 'Should return "(empty)" for empty library');

// Test with one book
testLibrary.addBook("978-0-123456-78-9", "The Great Gatsby", 3);
console.assert(shelfLine(testLibrary) === 'The Great Gatsby', 'Should return single title');

// Test with multiple books
testLibrary.addBook("978-0-987654-32-1", "1984");
testLibrary.addBook("978-0-111111-11-1", "Animal Farm", 1);
const result = shelfLine(testLibrary);
const expected = '1984, Animal Farm, The Great Gatsby';
console.assert(result === expected, `Should return sorted titles: ${expected}`);

console.log("All asserts passed!");

